"""Lazy Native map route discovery for the fixed hill-crest/change-lane cell."""
import math

from construction import validate_hill_route


def _lane_type(waypoint):
    return str(getattr(waypoint, 'lane_type', '')).split('.')[-1]


def _forward_dot(first, second):
    a = first.transform.get_forward_vector()
    b = second.transform.get_forward_vector()
    norm = math.hypot(a.x, a.y)*math.hypot(b.x, b.y)
    return (a.x*b.x+a.y*b.y)/norm if norm else -1.


def _adjacent(waypoint):
    for method in ('get_left_lane', 'get_right_lane'):
        candidate = getattr(waypoint, method)()
        if candidate is None or _lane_type(candidate) != 'Driving':
            continue
        if candidate.road_id == waypoint.road_id and candidate.lane_id != waypoint.lane_id:
            dot = _forward_dot(waypoint, candidate)
            if dot >= .8:
                return {'road_id': candidate.road_id, 'lane_id': candidate.lane_id,
                        'lane_type': 'Driving', 'forward_dot': dot}, candidate
    return None, None


def discover_hill_route(native_map, *, step_m=4., points=120,
                        crest_station_range_m=None, change_station_m=None,
                        seed_strategy='spawn'):
    """Choose connected original waypoints with crest and forward adjacent lane.

    Selection is geometric. A missing map feature is an explicit Native failure,
    never replaced by an authored label or a flat route.
    """
    if step_m <= 0 or points < 9:
        raise ValueError('invalid Native route search resolution')
    if seed_strategy == 'spawn':
        firsts = [native_map.get_waypoint(spawn.location)
                  for spawn in native_map.get_spawn_points()]
    elif seed_strategy == 'topology':
        firsts = native_map.generate_waypoints(20.0)
    else:
        raise ValueError('unknown Native route seed strategy')
    for first in firsts:
        if first is None or _lane_type(first) != 'Driving':
            continue
        waypoints = [first]
        while len(waypoints) < points:
            options = [p for p in waypoints[-1].next(step_m)
                       if p.road_id == first.road_id and p.lane_id == first.lane_id
                       and _lane_type(p) == 'Driving']
            if len(options) != 1:
                break
            point = options[0]
            if math.hypot(point.transform.location.x-waypoints[-1].transform.location.x,
                          point.transform.location.y-waypoints[-1].transform.location.y) > 1.5*step_m:
                break
            waypoints.append(point)
        if len(waypoints) != points:
            continue
        adjacent, target = _adjacent(waypoints[-2])
        if adjacent is None:
            continue
        samples = []
        station = 0.
        for i, wp in enumerate(waypoints):
            if i:
                previous = waypoints[i-1].transform.location
                here = wp.transform.location
                station += math.hypot(here.x-previous.x, here.y-previous.y)
            samples.append({'road_id': wp.road_id, 'lane_id': wp.lane_id,
                            'lane_type': _lane_type(wp), 'station_m': station,
                            'z_m': wp.transform.location.z,
                            'adjacent_lane': adjacent})
        try:
            geometry = validate_hill_route(samples)
        except ValueError:
            continue
        if crest_station_range_m is not None:
            low, high = crest_station_range_m
            if not low <= geometry['crest_station_m'] <= high:
                continue
        if change_station_m is not None:
            change_index = min(range(len(samples)),
                               key=lambda index: abs(samples[index]['station_m']-change_station_m))
            change_neighbor, _ = _adjacent(waypoints[change_index])
            if not change_neighbor or change_neighbor['lane_id'] != geometry['target_lane_id']:
                continue
        return {'map_source': native_map.name, 'route_source': 'Native CARLA connected waypoints',
                'waypoints': waypoints, 'target_waypoint': target,
                'sampled_geometry': samples, 'geometry': geometry}
    raise ValueError('original Native map lacks connected hill crest and forward adjacent lane')

"""CPU-checkable hill-crest following construction and controller primitives.

Native capture must supply map waypoints and original actor measurements. Targets
are engineering setpoints for a judgment sweep, never statutory cutoffs.
"""
import math


def _number(value, name):
    if type(value) not in (int, float) or not math.isfinite(value):
        raise ValueError(f'{name} must be finite')
    return float(value)


def validate_hill_route(samples):
    """Check a connected same-lane approach, crest, and outgoing lane option."""
    if not isinstance(samples, list) or len(samples) < 7:
        raise ValueError('hill approach route needs at least seven Native waypoints')
    road = samples[0]['road_id']
    lane = samples[0]['lane_id']
    if not all(p.get('road_id') == road and p.get('lane_id') == lane and
               p.get('lane_type') == 'Driving' for p in samples):
        raise ValueError('following route must stay on one driving lane')
    stations = [_number(p['station_m'], 'route station') for p in samples]
    heights = [_number(p['z_m'], 'waypoint elevation') for p in samples]
    if any(b-a <= 0 or b-a > 5.0 for a, b in zip(stations, stations[1:])):
        raise ValueError('Native route is disconnected or reversed')
    peak = max(range(2, len(samples)-2), key=lambda i: heights[i])
    if heights[peak]-heights[0] < 1.0 or heights[peak]-heights[-1] < .5:
        raise ValueError('no measured hill crest on selected route')
    if not (stations[peak]-stations[0] >= 12 and stations[-1]-stations[peak] >= 12):
        raise ValueError('insufficient following approach or lane-change exit')
    neighbor = samples[-2].get('adjacent_lane')
    if not isinstance(neighbor, dict) or neighbor.get('road_id') != road or neighbor.get('lane_type') != 'Driving':
        raise ValueError('same-road adjacent driving lane missing')
    if neighbor.get('lane_id') == lane or neighbor.get('forward_dot', 0) < .8:
        raise ValueError('adjacent lane is not a forward lane-change target')
    return {'crest_station_m': stations[peak], 'crest_z_m': heights[peak],
            'following_lane_id': lane, 'target_lane_id': neighbor['lane_id'],
            'road_id': road}


def speed_command(actual_speed_mps, target_speed_mps, gap_m, target_gap_m, relative_speed_mps):
    """Bounded throttle/brake for a requested gap, with closing-rate damping."""
    actual = _number(actual_speed_mps, 'actual speed')
    target = _number(target_speed_mps, 'target speed')
    gap = _number(gap_m, 'original body gap')
    desired = _number(target_gap_m, 'requested body gap')
    closing = _number(relative_speed_mps, 'relative speed')
    if min(actual, target, desired) < 0:
        raise ValueError('negative speed or requested gap')
    error = min(target-actual, .30*(gap-desired)-.8*closing)
    return {'throttle': max(0., min(.6, .22*error)),
            'brake': max(0., min(.8, -.35*error))}


def lane_change_phase(time_s, first_change_s, original_lane_id, observed_lane_id):
    """Gate the post-following maneuver using observed lane identity."""
    t = _number(time_s, 'original time')
    start = _number(first_change_s, 'lane-change start')
    if start <= 20:
        raise ValueError('steady 14..20s following window must precede lane change')
    if t < start:
        if observed_lane_id != original_lane_id:
            raise ValueError('lane changed during following window')
        return 'following'
    return 'changing' if observed_lane_id == original_lane_id else 'changed'

import sys
import unittest
from pathlib import Path
from types import SimpleNamespace

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from native_route import discover_hill_route


class Transform:
    def __init__(self, x, z, direction=1):
        self.location = SimpleNamespace(x=x, y=0, z=z)
        self.direction = direction

    def get_forward_vector(self):
        return SimpleNamespace(x=self.direction, y=0)


class Waypoint:
    def __init__(self, x, z, lane=-1, direction=1):
        self.road_id = 12
        self.lane_id = lane
        self.lane_type = 'Driving'
        self.transform = Transform(x, z, direction)
        self.successor = None
        self.left = None

    def next(self, distance):
        return [self.successor] if self.successor else []

    def get_left_lane(self):
        return self.left

    def get_right_lane(self):
        return None


class Map:
    name = 'fake original Native map'

    def __init__(self, heights, adjacent_direction=1):
        self.points = [Waypoint(i*4, z) for i, z in enumerate(heights)]
        for a, b in zip(self.points, self.points[1:]):
            a.successor = b
        self.points[-2].left = Waypoint(40, heights[-2], -2, adjacent_direction)

    def get_spawn_points(self):
        return [SimpleNamespace(location=self.points[0].transform.location)]

    def get_waypoint(self, location):
        return self.points[0]

    def generate_waypoints(self, spacing):
        return [self.points[0]]


class NativeRouteTest(unittest.TestCase):
    def test_map_discovery_uses_actual_elevation_and_forward_lane(self):
        route = discover_hill_route(Map([0,.1,.3,.7,1.1,1.7,2,1.8,1.4,1,.6,.2]), points=12)
        self.assertEqual(route['geometry']['target_lane_id'], -2)
        self.assertEqual(route['map_source'], 'fake original Native map')
        self.assertEqual(len(route['waypoints']), 12)

    def test_flat_and_opposing_adjacent_lane_rejected(self):
        for native_map in (Map([0]*12),
                           Map([0,.1,.3,.7,1.1,1.7,2,1.8,1.4,1,.6,.2], -1)):
            with self.subTest(native_map=native_map), self.assertRaisesRegex(ValueError, 'lacks connected hill crest'):
                discover_hill_route(native_map, points=12)

    def test_topology_fallback_uses_same_connected_route_without_spawn_seed(self):
        native_map = Map([0,.1,.3,.7,1.1,1.7,2,1.8,1.4,1,.6,.2])
        native_map.get_spawn_points = lambda: []
        with self.assertRaisesRegex(ValueError, 'lacks connected hill crest'):
            discover_hill_route(native_map, points=12)
        route = discover_hill_route(native_map, points=12,
                                    seed_strategy='topology')
        self.assertEqual(route['geometry']['target_lane_id'], -2)


if __name__ == '__main__':
    unittest.main()
